import { Clue, clueClass } from "./clue";

interface KeyboardProps {
  gameState: GameState;
  layout: string;
  letterInfo: Map<string, Clue>;
  onKey: (key: string) => void;
  guesses: string[];
  rowBorders: number[][];
}

enum GameState {
  Playing,
  Won,
  Lost,
}

export function Keyboard(props: KeyboardProps) {
  let keysMap: { [name: string]: number } = {
    a: 0,
    b: 0,
    c: 0,
    d: 0,
    e: 0,
    f: 0,
    g: 0,
    h: 0,
    i: 0,
    j: 0,
    k: 0,
    l: 0,
    m: 0,
    n: 0,
    o: 0,
    p: 0,
    q: 0,
    r: 0,
    s: 0,
    t: 0,
    u: 0,
    v: 0,
    w: 0,
    x: 0,
    y: 0,
    z: 0,
  };

  const setKeyBorders = () => {
    for (let i = 0; i < props.guesses.length; i++) {
      for (let j = 0; j < 5; j++) {
        const borderVal = props.rowBorders[i][j];
        if (borderVal > 0) {
          if (borderVal > keysMap[props.guesses[i][j]]) {
            keysMap[props.guesses[i][j]] = borderVal;
          }
        }
      }
    }
  };

  setKeyBorders();

  const keyboard = props.layout
    .split("-")
    .map((row) =>
      row
        .split("")
        .map((key) =>
          key
            .replace("B", "Backspace")
            .replace("E", props.gameState === GameState.Playing ? "Enter" : "Start")
        )
    );

  return (
    <div className="Game-keyboard" aria-hidden="true">
      {keyboard.map((row, i) => (
        <div key={i} className="Game-keyboard-row">
          {row.map((label, j) => {
            let className = "Game-keyboard-button";
            if (keysMap[label] === 2) {
              className += " border-correct";
            } else if (keysMap[label] === 1) {
              className += " border-incorrect";
            }
            const clue = props.letterInfo.get(label);
            if (clue !== undefined) {
              className += " " + clueClass(clue);
            }
            if (label.length > 1) {
              className += " Game-keyboard-button-wide";
            }
            return (
              <button
                tabIndex={-1}
                key={j}
                className={className}
                onClick={() => {
                  props.onKey(label);
                }}
              >
                {label.replace("Backspace", "⌫")}
              </button>
            );
          })}
        </div>
      ))}
    </div>
  );
}
