import "./App.css";
import { maxGuesses, fillArray } from "./util";
import Game from "./Game";
import { useEffect, useState } from "react";
import { About } from "./About";
import { Settings } from "./Settings";
import { Stats } from "./Stats";
import { Calendar } from "./Calendar";

let didLoad = false;

let loadGamesPlayed = 0;
let loadGamesWon = 0;
let loadCurrentStreak = 0;
let loadMaxStreak = 0;
let loadGuessDistribution = fillArray(maxGuesses - 1);
let loadDaily = true;

function loadItems() {
  let item = localStorage.getItem("gamesPlayed");
  loadGamesPlayed = item ? JSON.parse(item) : loadGamesPlayed;

  item = localStorage.getItem("gamesWon");
  loadGamesWon = item ? JSON.parse(item) : loadGamesWon;

  item = localStorage.getItem("currentStreak");
  loadCurrentStreak = item ? JSON.parse(item) : loadCurrentStreak;

  item = localStorage.getItem("maxStreak");
  loadMaxStreak = item ? JSON.parse(item) : loadMaxStreak;

  item = localStorage.getItem("guessDistribution");
  loadGuessDistribution = item ? JSON.parse(item) : loadGuessDistribution;

  item = localStorage.getItem("daily");
  loadDaily = item ? JSON.parse(item) : loadDaily;
}

function useSetting<T>(key: string, initial: T): [T, (value: T | ((t: T) => T)) => void] {
  const [current, setCurrent] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initial;
    } catch (e) {
      return initial;
    }
  });
  const setSetting = (value: T | ((t: T) => T)) => {
    try {
      const v = value instanceof Function ? value(current) : value;
      setCurrent(v);
      window.localStorage.setItem(key, JSON.stringify(v));
    } catch (e) {}
  };
  return [current, setSetting];
}

const now = new Date();

function App() {
  if (!didLoad) {
    loadItems();
    didLoad = true;
  }

  type Page = "game" | "about" | "settings" | "stats" | "calendar";
  const [page, setPage] = useState<Page>("game");
  const [daily, setDaily] = useState(loadDaily);
  const prefersDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
  const [dark, setDark] = useSetting<boolean>("dark", prefersDark);
  const [colorBlind, setColorBlind] = useSetting<boolean>("colorblind", false);
  const [keyboard, setKeyboard] = useSetting<string>("keyboard", "qwertyuiop-asdfghjkl-BzxcvbnmE");
  const [enterLeft, setEnterLeft] = useSetting<boolean>("enter-left", false);
  const [gamesPlayed, setGamesPlayed] = useState(loadGamesPlayed);
  const [gamesWon, setGamesWon] = useState(loadGamesWon);
  const [currentStreak, setCurrentStreak] = useState(loadCurrentStreak);
  const [maxStreak, setMaxStreak] = useState(loadMaxStreak);
  const [guessDistribution, setGuessDistribution] = useState<number[]>(loadGuessDistribution);

  useEffect(() => {
    document.body.className = dark ? "dark" : "";
    setTimeout(() => {
      document.body.style.transition = "0.3s background-color ease-out";
    }, 1);
  }, [dark]);

  const link = (emoji: string, label: string, page: Page) => (
    <button
      className="emoji-link"
      onClick={() => setPage(page)}
      title={label}
      aria-label={label}
    >
      {emoji}
    </button>
  );

  return (
    <div className={"App-container" + (colorBlind ? " color-blind" : "")}>
      <h1>
        <span className="Game-name">
          <img
            width="25"
            height="25"
            src={dark ? "faviconDark.png" : "favicon.png"}
            className="Favicon"
          ></img>
          Nordle
        </span>
      </h1>
      <div className="top-right">
        {page !== "game" ? (
          link("❌", "Close", "game")
        ) : (
          <>
            {link("❓", "About", "about")}
            {link("⚙️", "Settings", "settings")}
            {link("📊", "Stats", "stats")}
          </>
        )}
      </div>
      {page === "about" && <About />}
      {page === "settings" && (
        <Settings
          dark={dark}
          setDark={setDark}
          colorBlind={colorBlind}
          setColorBlind={setColorBlind}
          keyboard={keyboard}
          setKeyboard={setKeyboard}
          enterLeft={enterLeft}
          setEnterLeft={setEnterLeft}
        />
      )}
      {page === "stats" && (
        <Stats
          gamesPlayed={gamesPlayed}
          gamesWon={gamesWon}
          currentStreak={currentStreak}
          maxStreak={maxStreak}
          guessDistribution={guessDistribution}
        />
      )}
      {page === "calendar" && <Calendar />}
      <Game
        maxGuesses={maxGuesses}
        hidden={page !== "game"}
        colorBlind={colorBlind}
        keyboardLayout={keyboard.replaceAll(
          /[BE]/g,
          (x) => (enterLeft ? "EB" : "BE")["BE".indexOf(x)]
        )}
        guessDistribution={guessDistribution}
        setGuessDistribution={setGuessDistribution}
        gamesPlayed={gamesPlayed}
        setGamesPlayed={setGamesPlayed}
        gamesWon={gamesWon}
        setGamesWon={setGamesWon}
        currentStreak={currentStreak}
        setCurrentStreak={setCurrentStreak}
        maxStreak={maxStreak}
        setMaxStreak={setMaxStreak}
      />
    </div>
  );
}

export default App;
