import { Clue, clueClass, CluedLetter, clueWord } from "./clue";

export enum RowState {
  LockedIn,
  Editing,
  Pending,
}

interface RowProps {
  rowIndex: number;
  rowState: RowState;
  wordLength: number;
  cluedLetters: CluedLetter[];
  annotation?: string;
  isPlaying: boolean;
  rowBorders: number[][];
  setRowBorders: (value: number[][] | ((t: number[][]) => number[][])) => void;
}

let rowToKeyboardMap: { [name: string]: number } = {
  q: 0,
  w: 1,
  e: 2,
  r: 3,
  t: 4,
  y: 5,
  u: 6,
  i: 7,
  o: 8,
  p: 9,
  a: 10,
  s: 11,
  d: 12,
  f: 13,
  g: 14,
  h: 15,
  j: 16,
  k: 17,
  l: 18,
  z: 20,
  x: 21,
  c: 22,
  v: 23,
  b: 24,
  n: 25,
  m: 26,
};

export function Row(props: RowProps) {
  const isLockedIn = props.rowState === RowState.LockedIn;
  const isEditing = props.rowState === RowState.Editing;
  const letterDivs = props.cluedLetters
    .concat(Array(props.wordLength).fill({ clue: Clue.Absent, letter: "" }))
    .slice(0, props.wordLength)
    .map(({ clue, letter }, i) => {
      let letterClass = "Row-letter";
      if (isLockedIn && clue !== undefined) {
        letterClass += " " + clueClass(clue);
      }
      let borderVal = props.rowBorders[props.rowIndex][i];
      if (borderVal === 2) {
        letterClass += " border-correct";
      } else if (borderVal === 1) {
        letterClass += " border-incorrect";
      }

      let startPress = 0;
      const delay = 310;

      const toggleBorder = (e: React.MouseEvent, toggleVal: number) => {
        const eventTarget = e.target as HTMLTableCellElement;
        const rowIdx = (eventTarget.parentNode as HTMLTableRowElement).rowIndex;
        const colIdx = eventTarget.cellIndex;
        const rowBorders = [...props.rowBorders];
        const borderVal = rowBorders[rowIdx][colIdx];

        if (borderVal === toggleVal) {
          rowBorders[rowIdx][colIdx] = 0;
        } else {
          rowBorders[rowIdx][colIdx] = toggleVal;
        }

        props.setRowBorders(rowBorders);
      };

      const onClick = (e: React.MouseEvent) => {
        if (props.isPlaying) {
          if (isLockedIn) {
            if (Date.now() - startPress < delay) {
              toggleBorder(e, 1);
            }
          }
        }
      };

      const onMouseDown = (e: React.MouseEvent) => {
        startPress = Date.now();
        if (props.isPlaying) {
          if (isLockedIn) {
            if (e.button === 2) {
              toggleBorder(e, 2);
            }
          }
        }
      };

      const onMouseUp = (e: React.MouseEvent) => {
        if (props.isPlaying) {
          if (isLockedIn) {
            if (Date.now() - startPress >= delay && e.button !== 2) {
              toggleBorder(e, 2);
            }
          }
        }
      };

      return (
        <td
          key={i}
          className={letterClass}
          aria-live={isEditing ? "assertive" : "off"}
          aria-label={isLockedIn ? letter.toUpperCase() + (clue === undefined ? "" : ": " + clueWord(clue)): ""}
          onClick={onClick}
          onMouseDown={onMouseDown}
          onMouseUp={onMouseUp}
          onContextMenu={isLockedIn ? (event) => event.preventDefault() : () => {}}
        >
          {letter}
        </td>
      );
    });
  let rowClass = "Row";
  if (isLockedIn) rowClass += " Row-locked-in";
  return (
    <tr className={rowClass}>
      {letterDivs}
      {props.annotation && (<span className="Row-annotation">{props.annotation}</span>)}
    </tr>
  );
}
