import { Clue } from "./clue";
import { Row, RowState } from "./Row";
import { gameName, maxGuessLength, maxGuesses, fill2DArray } from "./util";

const rowBorders = fill2DArray(maxGuesses, maxGuessLength);
let setRowBorders: (value: number[][] | ((t: number[][]) => number[][])) => void;

export function About() {
  return (
    <div className="App-about">
      <p>
        <i>{gameName}</i> is a variation of{" "}
        <a href="https://www.nytimes.com/games/wordle/index.html">
          <i>Wordle</i>
        </a>{" "}
        by <a href="https://twitter.com/powerlanguish">powerlanguage</a>
      </p>
      <p>
        You get up to {maxGuesses - 1} guesses to unveil the target word
        <br />
        Like Wordle, each tile of a given guess has color coded hints
        <br />
        The only caveat is that{" "}
        <i style={{ color: "red" }}>
          {" "}
          each hint is a <em>LIE!</em>
        </i>
      </p>
      <hr />
      <table
        className="Game-rows"
        tabIndex={0}
        aria-label="Row of an example guess"
      >
        <tbody>
          {
            <Row
              rowIndex={0}
              rowState={RowState.LockedIn}
              wordLength={5}
              cluedLetters={[
                { clue: Clue.Correct, letter: "t" },
                { clue: Clue.Elsewhere, letter: "e" },
                { clue: Clue.Absent, letter: "n" },
                { clue: Clue.Elsewhere, letter: "e" },
                { clue: Clue.Correct, letter: "t" },
              ]}
              isPlaying={false}
              rowBorders={rowBorders}
              setRowBorders={setRowBorders}
            />
          }
        </tbody>
      </table>
      <p>
        The first and last letters cannot be <b className={"green-bg"}>T</b>
        <br />
        <strong>It is not here, but it might be elsewhere</strong>
        <br />
      </p>
      <p>
        Either <b className={"yellow-bg"}>E</b> is in both the 2nd and 4th
        slots, or it is not in the word at all
        <br />
        <strong>It is either everywhere it is yellow or nowhere</strong>
      </p>
      <p>
        <b>N</b> is in the target word
        <br />
        <strong>Possibly in the correct place; possibly not</strong>
      </p>
      <hr />
      <table
        className="Game-rows"
        tabIndex={0}
        aria-label="Row of an example guess"
      >
        <tbody>
          {
            <Row
              rowIndex={0}
              rowState={RowState.LockedIn}
              wordLength={5}
              cluedLetters={[
                { clue: Clue.Correct, letter: "g" },
                { clue: Clue.Elsewhere, letter: "u" },
                { clue: Clue.Absent, letter: "e" },
                { clue: Clue.Elsewhere, letter: "s" },
                { clue: Clue.Correct, letter: "s" },
              ]}
              isPlaying={false}
              rowBorders={rowBorders}
              setRowBorders={setRowBorders}
            />
          }
        </tbody>
      </table>
      <p>
        <strong>There are up to 2 types of hints shown per guessed letter</strong>
        <br />
        When it matches its respective target letter <b className={"yellow-bg"}>S</b>
        <br />
        When it does not <b className={"green-bg"}>S</b>
      </p>
      <hr />
      <p>
        Code based on a fork of{" "}
        <a href="https://github.com/lynn/hello-wordl">hello wordl</a>
      </p>
    </div>
  );
}
