import { useEffect, useRef, useState } from "react";
import { Row, RowState } from "./Row";
import dictionary from "./dictionary.json";
import { Clue, wordleClue, clue, describeClue } from "./clue";
import { Keyboard } from "./Keyboard";
import targets from "./targets.json";
import { gameName, speak, maxGuesses, maxGuessLength, fillArray, fill2DArray } from "./util";

enum GameState {
  Playing,
  Won,
  Lost,
}

interface GameProps {
  maxGuesses: number;
  hidden: boolean;
  colorBlind: boolean;
  keyboardLayout: string;
  guessDistribution: number[];
  setGuessDistribution: (value: number[] | ((t: number[]) => number[])) => void;
  gamesPlayed: number;
  setGamesPlayed: (value: number | ((t: number) => number)) => void;
  gamesWon: number;
  setGamesWon: (value: number | ((t: number) => number)) => void;
  currentStreak: number;
  setCurrentStreak: (value: number | ((t: number) => number)) => void;
  maxStreak: number;
  setMaxStreak: (value: number | ((t: number) => number)) => void;
}

const defaultHint = `Lies – they're everywhere`;
let didLoad = false;

let loadState = GameState.Playing;
let loadGameNumber = 1;
let loadGuesses: string[] = [];
let loadTarget = "";
let loadHint = "";
let loadAlphabetCluesMap: { [key: string]: number } = getRandomClues();
let loadRowBorders = fill2DArray(maxGuesses, maxGuessLength);

function loadItems() {
  let item = localStorage.getItem("gameState");
  loadState = item ? JSON.parse(item) : loadState;

  item = localStorage.getItem("gameNumber");
  loadGameNumber = item ? JSON.parse(item) : loadGameNumber;

  item = localStorage.getItem("guesses");
  loadGuesses = item ? JSON.parse(item) : loadGuesses;

  item = localStorage.getItem("target");
  loadTarget = item ? JSON.parse(item) : loadTarget;

  item = localStorage.getItem("alphabetCluesMap");
  loadAlphabetCluesMap = item ? JSON.parse(item) : loadAlphabetCluesMap;

  if (loadState === GameState.Won) {
    loadHint = `You won! The answer was ${loadTarget.toUpperCase()}`;
  } else if (loadState === GameState.Lost) {
    loadHint = `You lost! The answer was ${loadTarget.toUpperCase()}`;
  } else {
    loadHint = defaultHint;
  }

  item = localStorage.getItem("rowBorders");
  loadRowBorders = item ? JSON.parse(item) : loadRowBorders;
}

function randomWord(wordLength: number, filterString: string = ""): string {
  let candidate: string;
  do {
    candidate = targets[Math.floor(targets.length * Math.random())];
  } while (candidate === filterString);
  return candidate;
}

function getRandomClues() {
  const addRandomClues = (alphabetCluesMap: { [key: string]: number }, alphabet: string, offset: number ) => {
    const zeroEnd = Math.floor((alphabet.length + offset * 2) / 2);
    const values = fillArray(zeroEnd); // Green hints

    while (values.length !== alphabet.length) {
      values.push(1); // Yellow hints
    }

    values.sort(() => Math.random() - 0.5);

    for (let letter of alphabet) {
      alphabetCluesMap[letter] = values.shift();
    }
  };

  const vowels = "aeiou";
  const consonants = "bcdfghjklmnpqrstvwxyz";
  const alphabetCluesMap: { [key: string]: number } = {};

  addRandomClues(alphabetCluesMap, vowels, 0);
  addRandomClues(alphabetCluesMap, consonants, 1);

  return alphabetCluesMap;
}

function Game(props: GameProps) {
  if (!didLoad) {
    loadItems();
    didLoad = true;
  }

  const targ = randomWord(maxGuessLength);

  const [gameState, setGameState] = useState(loadState);
  const [guesses, setGuesses] = useState<string[]>(loadGuesses.length !== 0 ? loadGuesses : [targ]);
  const [currentGuess, setCurrentGuess] = useState<string>("");
  const [wordLength, setWordLength] = useState(maxGuessLength);
  const [gameNumber, setGameNumber] = useState(loadGameNumber);
  const [target, setTarget] = useState(loadTarget ? loadTarget : randomWord(maxGuessLength, targ));
  const [hint, setHint] = useState<string>(loadHint);
  const [alphabetCluesMap, setAlphabetCluesMap] = useState(loadAlphabetCluesMap);
  const [rowBorders, setRowBorders] = useState(loadRowBorders);

  localStorage.setItem("gameState", JSON.stringify(gameState));
  localStorage.setItem("gameNumber", JSON.stringify(gameNumber));
  localStorage.setItem("guesses", JSON.stringify(guesses));
  localStorage.setItem("target", JSON.stringify(target));
  localStorage.setItem("alphabetCluesMap", JSON.stringify(alphabetCluesMap));
  localStorage.setItem("rowBorders", JSON.stringify(rowBorders));

  const tableRef = useRef<HTMLTableElement>(null);
  const startNextGame = () => {
    const newTarget = randomWord(maxGuessLength);

    setAlphabetCluesMap(getRandomClues());
    setRowBorders(fill2DArray(maxGuesses, maxGuessLength));
    setTarget(randomWord(maxGuessLength, newTarget));
    setHint(defaultHint);
    setWordLength(maxGuessLength);
    setGuesses([newTarget]);
    setCurrentGuess("");
    setGameState(GameState.Playing);
    setGameNumber((x) => x + 1);
  };

  async function share(copiedHint: string, text?: string) {
    const body = text ? text : "";
    if (
      /android|iphone|ipad|ipod|webos/i.test(navigator.userAgent) &&
      !/firefox/i.test(navigator.userAgent)
    ) {
      try {
        await navigator.share({ text: body });
        return;
      } catch (e) {
        console.warn("navigator.share failed:", e);
      }
    }
    try {
      await navigator.clipboard.writeText(body);
      setHint(copiedHint);
      return;
    } catch (e) {
      console.warn("navigator.clipboard.writeText failed:", e);
    }
  }

  const onKey = (key: string) => {
    if (gameState !== GameState.Playing) {
      if (key === "Enter" || key === "Start") {
        startNextGame();
      }
      return;
    }
    if (guesses.length === props.maxGuesses) return;
    if (/^[a-z]$/i.test(key)) {
      setCurrentGuess((guess) =>
        (guess + key.toLowerCase()).slice(0, wordLength)
      );
      tableRef.current?.focus();
      setHint("");
    } else if (key === "Backspace") {
      setCurrentGuess((guess) => guess.slice(0, -1));
      setHint("");
    } else if (key === "Enter") {
      if (currentGuess.length !== wordLength) {
        setHint("Too short");
        return;
      }
      if (guesses.indexOf(currentGuess) !== -1) {
        setHint("Already played");
        return;
      }
      if (!dictionary.includes(currentGuess)) {
        setHint("Not a valid word");
        return;
      }
      setGuesses((guesses) => guesses.concat([currentGuess]));
      setCurrentGuess((guess) => "");

      const gameOver = (verbed: string) => {
        const gamesPlayed = props.gamesPlayed + 1;
        let gamesWon = props.gamesWon;
        let currentStreak = props.currentStreak;
        let maxStreak = props.maxStreak;
        const guessDistribution = [...props.guessDistribution];

        if (verbed === "won") {
          gamesWon += 1;
          currentStreak += 1;
          maxStreak = currentStreak > maxStreak ? currentStreak : maxStreak;
          guessDistribution[guesses.length - 1] += 1;
        } else {
          currentStreak = 0;
        }

        props.setGamesPlayed(gamesPlayed);
        props.setGamesWon(gamesWon);
        props.setCurrentStreak(currentStreak);
        props.setMaxStreak(maxStreak);
        props.setGuessDistribution(guessDistribution);

        localStorage.setItem("gamesPlayed", JSON.stringify(gamesPlayed));
        localStorage.setItem("gamesWon", JSON.stringify(gamesWon));
        localStorage.setItem("currentStreak", JSON.stringify(currentStreak));
        localStorage.setItem("maxStreak", JSON.stringify(maxStreak));
        localStorage.setItem("guessDistribution", JSON.stringify(guessDistribution));

        return `You ${verbed}! The answer was ${target.toUpperCase()}`;
      };

      if (currentGuess === target) {
        setHint(gameOver("won"));
        setGameState(GameState.Won);
      } else if (guesses.length + 1 === props.maxGuesses) {
        setHint(gameOver("lost"));
        setGameState(GameState.Lost);
      } else {
        setHint("");
        speak(describeClue(clue(currentGuess, target, alphabetCluesMap)));
      }
    }
  };

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (!e.ctrlKey && !e.metaKey) {
        onKey(e.key);
      }
      if (e.key === "Backspace") {
        e.preventDefault();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [currentGuess, gameState]);

  let letterInfo = new Map<string, Clue>();
  const tableRows = new Array(props.maxGuesses)
    .fill(undefined)
    .map((_, i) => {
      const guess = [...guesses, currentGuess][i] ?? "";
      const cluedLetters = clue(guess, target, alphabetCluesMap);
      const lockedIn = i < guesses.length;
      if (lockedIn) {
        for (const { clue, letter } of cluedLetters) {
          if (clue === undefined) break;
          const old = letterInfo.get(letter);
          if (old === undefined || clue === 0) {
            letterInfo.set(letter, clue);
          }
        }
      }
      return (
        <Row
          key={i}
          rowIndex={i}
          wordLength={wordLength}
          rowState={
            lockedIn
              ? RowState.LockedIn
              : i === guesses.length
              ? RowState.Editing
              : RowState.Pending
          }
          cluedLetters={cluedLetters}
          isPlaying={gameState === GameState.Playing ? true : false}
          rowBorders={rowBorders}
          setRowBorders={setRowBorders}
        />
      );
    });

  return (
    <div className="Game" style={{ display: props.hidden ? "none" : "block" }}>
      <div className="Game-options">
        <span>Game {gameNumber}</span>
      </div>
      <table
        className="Game-rows"
        tabIndex={0}
        aria-label="Table of guesses"
        ref={tableRef}
      >
        <tbody>{tableRows}</tbody>
      </table>
      <div className="share">
        <p
          role="alert"
          style={{
            userSelect: /https?:/.test(hint) ? "text" : "none",
            whiteSpace: "pre-wrap",
          }}
        >
          {hint || `\u00a0`}
        </p>
        <p>
          {gameState !== GameState.Playing && (
            <button
              onClick={() => {
                const emoji = props.colorBlind
                  ? ["⬛", "🟦", "🟧"]
                  : ["⬛", "🟨", "🟩"];
                const score =
                  gameState === GameState.Lost ? "X" : guesses.length - 1;
                share(
                  "Result copied to clipboard!",
                  `${gameName} #${gameNumber} ${score}/${
                    props.maxGuesses - 1
                  }\n` +
                    guesses
                      .map((guess) =>
                        wordleClue(guess, target)
                          .map((c) => emoji[c.clue ?? 0])
                          .join("")
                      )
                      .join("\n")
                );
              }}
            >
              Share
            </button>
          )}
        </p>
      </div>
      <Keyboard
        gameState={gameState}
        layout={props.keyboardLayout}
        letterInfo={letterInfo}
        onKey={onKey}
        guesses={guesses}
        rowBorders={rowBorders}
      />
    </div>
  );
}

export default Game;
