interface SettingsProps {
  dark: boolean;
  setDark: (value: boolean | ((t: boolean) => boolean)) => void;
  colorBlind: boolean;
  setColorBlind: (value: boolean | ((t: boolean) => boolean)) => void;
  keyboard: string;
  setKeyboard: (value: string | ((t: string) => string)) => void;
  enterLeft: boolean;
  setEnterLeft: (value: boolean | ((t: boolean) => boolean)) => void;
}

export function Settings(props: SettingsProps) {
  return (
    <div className="Settings">
      <div className="Settings-setting">
        <input
          id="dark-setting"
          type="checkbox"
          checked={props.dark}
          onChange={() => props.setDark((x: boolean) => !x)}
        />
        <label htmlFor="dark-setting">Dark theme</label>
      </div>
      <div className="Settings-setting">
        <input
          id="colorblind-setting"
          type="checkbox"
          checked={props.colorBlind}
          onChange={() => props.setColorBlind((x: boolean) => !x)}
        />
        <label htmlFor="colorblind-setting">High-contrast colors</label>
      </div>
      <div className="Settings-setting">
        <label htmlFor="keyboard-setting">Keyboard layout:</label>
        <select
          name="keyboard-setting"
          id="keyboard-setting"
          value={props.keyboard}
          onChange={(e) => props.setKeyboard(e.target.value)}
        >
          <option value="qwertyuiop-asdfghjkl-BzxcvbnmE">QWERTY</option>
          <option value="azertyuiop-qsdfghjklm-BwxcvbnE">AZERTY</option>
          <option value="qwertzuiop-asdfghjkl-ByxcvbnmE">QWERTZ</option>
          <option value="BpyfgcrlE-aoeuidhtns-qjkxbmwvz">Dvorak</option>
          <option value="qwfpgjluy-arstdhneio-BzxcvbkmE">Colemak</option>
        </select>
        <input
          style={{ marginLeft: 20 }}
          id="enter-left-setting"
          type="checkbox"
          checked={props.enterLeft}
          onChange={() => props.setEnterLeft((x: boolean) => !x)}
        />
        <label htmlFor="enter-left-setting">"Enter" on left side</label>
      </div>
    </div>
  );
}
