import dictionary from "./dictionary.json";

export const gameName = "Nordle";
export const maxGuesses = 10;
export const maxGuessLength = 5;

export const fillArray = (width: number) => {
  return new Array(width).fill(0);
}

export const fill2DArray = (length: number, width: number) => {
  return new Array(length).fill(0).map(() => Array(width).fill(0));
}

// https://a11y-guidelines.orange.com/en/web/components-examples/make-a-screen-reader-talk/
export function speak(text: string, priority: "polite" | "assertive" = "assertive") {
  var el = document.createElement("div");
  var id = "speak-" + Date.now();
  el.setAttribute("id", id);
  el.setAttribute("aria-live", priority || "polite");
  el.classList.add("sr-only");
  document.body.appendChild(el);

  window.setTimeout(function () {
    document.getElementById(id)!.innerHTML = text;
  }, 100);

  window.setTimeout(function () {
    document.body.removeChild(document.getElementById(id)!);
  }, 1000);
}
