export enum Clue {
  Absent,
  Elsewhere,
  Correct,
}

export interface CluedLetter {
  clue?: Clue;
  letter: string;
}

export function wordleClue(word: string, target: string): CluedLetter[] {
  return word.split("").map((letter: string, i) => {
    if (target[i] === letter) {
      return { clue: Clue.Correct, letter };
    } else if (target.indexOf(letter) > -1) {
      return { clue: Clue.Elsewhere, letter };
    } else {
      return { clue: Clue.Absent, letter };
    }
  });
}

export function clue(word: string, target: string, alphabetCluesMap: { [key: string]: number }): CluedLetter[] {
  return word.split("").map((letter: string, i) => {
    let randomClueValue: number = alphabetCluesMap[letter];
    if (target[i] === letter) {
      if (randomClueValue) {
        return { clue: Clue.Elsewhere, letter };
      }
      return { clue: Clue.Absent, letter };
    } else if (target.indexOf(letter) > -1) {
      if (randomClueValue) {
        return { clue: Clue.Absent, letter };
      }
      return { clue: Clue.Correct, letter };
    } else {
      if (randomClueValue) {
        return { clue: Clue.Elsewhere, letter };
      }
      return { clue: Clue.Correct, letter };
    }
  });
}

export function clueClass(clue: Clue): string {
  if (clue === Clue.Absent) {
    return "letter-absent";
  } else if (clue === Clue.Elsewhere) {
    return "letter-elsewhere";
  } else {
    return "letter-correct";
  }
}

export function clueWord(clue: Clue): string {
  if (clue === Clue.Absent) {
    return "no";
  } else if (clue === Clue.Elsewhere) {
    return "elsewhere";
  } else {
    return "correct";
  }
}

export function describeClue(clue: CluedLetter[]): string {
  return clue
    .map(({ letter, clue }) => letter.toUpperCase() + " " + clueWord(clue!))
    .join(", ");
}
