interface StatsProps {
  gamesPlayed: number;
  gamesWon: number;
  currentStreak: number;
  maxStreak: number;
  guessDistribution: number[];
}

export function Stats(props: StatsProps) {
  const maxDistributionValue = Math.max(...props.guessDistribution);
  const percentages = new Array(props.guessDistribution.length).fill(7);

  if (props.gamesPlayed > 0) {
    for (let i = 0; i < props.guessDistribution.length; i++) {
      if (props.guessDistribution[i] !== 0) {
        percentages[i] = 7 + Math.ceil(93 * (props.guessDistribution[i] / maxDistributionValue));
      }
    }
  }

  return (
    <div className="Game-stats">
      <h1>stats</h1>
      <div className="Game-stats-games">
        <div className="stat">
          <div className="stat-num">{props.gamesPlayed}</div>
          <div className="stat-label">played</div>
        </div>
        <div className="stat">
          <div className="stat-num">
            {props.gamesPlayed === 0 ? 0 : Math.floor((100 * props.gamesWon) / props.gamesPlayed)}
          </div>
          <div className="stat-label">win %</div>
        </div>
        <div className="stat">
          <div className="stat-num">{props.currentStreak}</div>
          <div className="stat-label">streak</div>
        </div>
        <div className="stat">
          <div className="stat-num">{props.maxStreak}</div>
          <div className="stat-label">max streak</div>
        </div>
      </div>
      <h1>guess distribution</h1>
      <div className="Game-stats-guesses">
        {percentages.map((percentage, i) => (
          <div className="guess-stat" key={i}>
            <div className="guess-count">{i + 1}</div>
            <div className="guess-graph">
              <div className="guess-bar" style={{ width: `${percentage}%` }}>
                <div className="guess-games">{props.guessDistribution[i]}</div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
